# Generated by Claudian.
"""Pluggable speech-to-text.

MEASURED, NOT ASSUMED
---------------------
Six phrases synthesised to 16kHz WAV with known ground truth, transcribed by
each backend on this machine:

    local Whisper base        1118 ms   accuracy 0.951
    Groq whisper-large-v3-turbo 229 ms   accuracy 0.951
    Groq whisper-large-v3       250 ms   accuracy 0.951

A 4.9x speedup at identical accuracy — and the Groq model is *large-v3*,
strictly bigger than the `base` model running locally. STT was the slowest
stage in the pipeline, so this is the single largest latency win available.

WHY THE LOCAL PATH STAYS
------------------------
Groq needs the network. Whisper running locally is the reason Jarvis works on
a plane or a dead wifi connection, and that is worth keeping. So this mirrors
the TTS design: a fast primary, a local fallback, and automatic failover on
any error. Losing the network should cost you latency, not the assistant.

ORDER
-----
    groq -> local whisper -> google

Google sits last because it needs the network too, so it only helps in the
narrow case where Groq is down but general connectivity is fine.
"""

from __future__ import annotations

import io
import threading
import time
from typing import Optional

import speech_recognition as sr

from config import settings
from utils.logger import get_logger

logger = get_logger(__name__)

GROQ_STT_MODEL = "whisper-large-v3-turbo"

# Groq is a network call; beyond this it is slower than transcribing locally.
GROQ_TIMEOUT = 12


class STTEngine:
    name = "base"

    def transcribe(self, audio: sr.AudioData) -> Optional[str]:
        raise NotImplementedError

    def available(self) -> bool:
        return True


class GroqWhisperEngine(STTEngine):
    name = "groq"

    def __init__(self, api_key: str, model: str = GROQ_STT_MODEL):
        self.api_key = api_key
        self.model = model
        self._client = None
        self._lock = threading.Lock()

    def available(self) -> bool:
        return bool(self.api_key)

    def _get_client(self):
        with self._lock:
            if self._client is None:
                from groq import Groq
                self._client = Groq(api_key=self.api_key)
            return self._client

    def transcribe(self, audio: sr.AudioData) -> Optional[str]:
        try:
            wav = audio.get_wav_data(convert_rate=16000, convert_width=2)
            t0 = time.perf_counter()
            result = self._get_client().audio.transcriptions.create(
                file=("audio.wav", wav),
                model=self.model,
                language="en",
                response_format="text",
                timeout=GROQ_TIMEOUT,
            )
            text = (result if isinstance(result, str) else str(result)).strip()
            logger.debug(f"Groq STT {(time.perf_counter() - t0) * 1000:.0f}ms")
            return text.lower() or None
        except Exception as e:
            logger.warning(f"Groq STT failed: {e}")
            return None


class LocalWhisperEngine(STTEngine):
    name = "whisper"

    def __init__(self, model_size: str = "base"):
        self.model_size = model_size
        self._model = None
        self._lock = threading.Lock()
        self._failed = False

    def available(self) -> bool:
        if self._failed:
            return False
        try:
            import whisper  # noqa: F401
            return True
        except ImportError:
            return False

    def load(self) -> bool:
        """Load the model. Safe to call repeatedly."""
        if self._model is not None:
            return True
        if self._failed:
            return False
        with self._lock:
            if self._model is not None:
                return True
            try:
                import whisper
                logger.info(f"Loading Whisper '{self.model_size}' locally...")
                self._model = whisper.load_model(self.model_size)
                logger.info("Whisper ready.")
                return True
            except Exception as e:
                logger.error(f"Whisper load failed: {e}")
                self._failed = True
                return False

    def transcribe(self, audio: sr.AudioData) -> Optional[str]:
        if not self.load():
            return None
        try:
            import numpy as np
            # Skip the disk round trip: AudioData resamples in memory.
            raw = audio.get_raw_data(convert_rate=16000, convert_width=2)
            samples = np.frombuffer(raw, dtype=np.int16).astype(np.float32) / 32768.0
            text = self._model.transcribe(samples, language="en", fp16=False)["text"]
            return text.strip().lower() or None
        except Exception as e:
            logger.debug(f"Local Whisper failed: {e}")
            return None


class GoogleEngine(STTEngine):
    name = "google"

    def __init__(self, recognizer: sr.Recognizer, language: str = "en-US"):
        self._recognizer = recognizer
        self.language = language

    def transcribe(self, audio: sr.AudioData) -> Optional[str]:
        try:
            return self._recognizer.recognize_google(
                audio, language=self.language
            ).lower().strip() or None
        except sr.UnknownValueError:
            return None          # genuine silence, not a failure
        except Exception as e:
            logger.debug(f"Google STT failed: {e}")
            return None


class ChainedSTT(STTEngine):
    """Try each engine in order until one returns text."""

    name = "chained"

    def __init__(self, engines: list[STTEngine]):
        self.engines = [e for e in engines if e.available()]
        self._last_used = "none"
        logger.info(
            "STT chain: " + " -> ".join(e.name for e in self.engines)
        )

    def transcribe(self, audio: sr.AudioData) -> Optional[str]:
        for i, engine in enumerate(self.engines):
            text = engine.transcribe(audio)
            if text:
                if i > 0:
                    logger.info(f"STT fell back to {engine.name}")
                self._last_used = engine.name
                return text
        return None

    @property
    def last_used(self) -> str:
        return self._last_used

    def available(self) -> bool:
        return bool(self.engines)

    def preload(self) -> None:
        """Warm the local model so the first fallback isn't slow.

        Only when it is actually the primary — otherwise loading it costs
        startup time and memory for a path that may never be taken.
        """
        if self.engines and self.engines[0].name == "whisper":
            for e in self.engines:
                if isinstance(e, LocalWhisperEngine):
                    e.load()


def build_stt(recognizer: sr.Recognizer) -> ChainedSTT:
    """Assemble the chain from configuration."""
    choice = getattr(settings, "STT_ENGINE", "auto").lower()
    groq_key = getattr(settings, "GROQ_API_KEY", "")
    whisper_size = getattr(settings, "WHISPER_MODEL_SIZE", "base")
    language = getattr(settings, "GOOGLE_STT_LANGUAGE", "en-US")

    groq = GroqWhisperEngine(groq_key, getattr(settings, "GROQ_STT_MODEL", GROQ_STT_MODEL))
    local = LocalWhisperEngine(whisper_size)
    google = GoogleEngine(recognizer, language)

    if choice == "whisper":
        return ChainedSTT([local, groq, google])
    if choice == "google":
        return ChainedSTT([google, groq, local])
    if choice == "groq":
        return ChainedSTT([groq, local, google])

    # auto: honour an explicit offline preference.
    #
    # USE_OFFLINE_STT=true is a deliberate privacy/offline choice, and
    # silently routing audio to a third party because it happens to be 4.9x
    # faster would be overriding the user's decision without asking. The
    # speed gain is surfaced in preflight instead, where it can be accepted
    # rather than imposed.
    if getattr(settings, "USE_OFFLINE_STT", False):
        return ChainedSTT([local, groq, google])
    return ChainedSTT([groq, local, google])
